<?php defined('_JEXEC') or die;
use DeCaro\Component\Forms\Administrator\Helper\FormHelper; use Joomla\CMS\Language\Text; use Joomla\CMS\Router\Route;
?>
<style>.df-dashboard{--df:#e60046;max-width:none;}.df-dhead{display:flex;justify-content:space-between;align-items:flex-end;gap:14px;margin:4px 0 18px}.df-dhead h2{margin:0;font-size:28px}.df-dhead p{margin:5px 0 0;color:var(--bs-secondary-color,#667085)}.df-actions{display:flex;gap:8px;flex-wrap:wrap}.df-btn{display:inline-flex;align-items:center;justify-content:center;min-height:39px;padding:0 14px;border:1px solid var(--bs-border-color,#d9dee5);border-radius:6px;background:var(--bs-body-bg,#fff);color:inherit!important;text-decoration:none;font-weight:700}.df-primary{background:var(--df);border-color:var(--df);color:#fff!important}.df-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:16px}.df-dashboard-card{border:1px solid var(--bs-border-color,#dfe3e7);border-radius:8px;background:var(--bs-body-bg,#fff);overflow:hidden}.df-stat{padding:17px}.df-stat small{display:block;text-transform:uppercase;font-size:11px;font-weight:800;color:var(--bs-secondary-color,#667085)}.df-stat strong{display:block;font-size:30px;margin-top:4px}.df-panels{display:grid;grid-template-columns:1fr 1fr;gap:14px}.df-dashboard-card-head{display:flex;justify-content:space-between;align-items:center;padding:14px 16px;background:var(--bs-tertiary-bg,#f7f8fa);border-bottom:1px solid var(--bs-border-color,#dfe3e7)}.df-dashboard-card-head h3{margin:0;font-size:18px}.df-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;align-items:center;padding:12px 16px;border-bottom:1px solid var(--bs-border-color,#e7eaee)}.df-row:last-child{border-bottom:0}.df-row small{display:block;color:var(--bs-secondary-color,#667085)}.df-num{font-weight:850;font-size:18px}.df-empty{padding:22px 16px;color:var(--bs-secondary-color,#667085)}@media(max-width:900px){.df-stats{grid-template-columns:1fr 1fr}.df-panels{grid-template-columns:1fr}}@media(max-width:520px){.df-dhead{flex-direction:column;align-items:flex-start}.df-stats{grid-template-columns:1fr}}</style>
<div class="df-dashboard"><div class="df-dhead"><div><h2><?php echo Text::_('COM_DECAROFORMS_DASHBOARD'); ?></h2><p><?php echo Text::_('COM_DECAROFORMS_DASHBOARD_DESC'); ?></p></div><div class="df-actions"><a class="df-btn" href="<?php echo $this->importUrl; ?>"><?php echo Text::_('COM_DECAROFORMS_MENU_IMPORT'); ?></a><a class="df-btn df-primary" href="<?php echo $this->builderUrl; ?>"><?php echo Text::_('COM_DECAROFORMS_CREATE_FORM'); ?></a></div></div>
<div class="df-stats"><div class="df-dashboard-card df-stat"><small><?php echo Text::_('COM_DECAROFORMS_TOTAL_FORMS'); ?></small><strong><?php echo (int)$this->stats['forms']; ?></strong></div><div class="df-dashboard-card df-stat"><small><?php echo Text::_('COM_DECAROFORMS_ACTIVE_FORMS'); ?></small><strong><?php echo (int)$this->stats['active']; ?></strong></div><div class="df-dashboard-card df-stat"><small><?php echo Text::_('COM_DECAROFORMS_TOTAL_SUBMISSIONS'); ?></small><strong><?php echo (int)$this->stats['submissions']; ?></strong></div><div class="df-dashboard-card df-stat"><small><?php echo Text::_('COM_DECAROFORMS_TODAY_SUBMISSIONS'); ?></small><strong><?php echo (int)$this->stats['today']; ?></strong></div></div>
<div class="df-panels"><section class="df-dashboard-card"><div class="df-dashboard-card-head"><h3><?php echo Text::_('COM_DECAROFORMS_FORMS'); ?></h3><a href="<?php echo $this->formsUrl; ?>"><?php echo Text::_('COM_DECAROFORMS_VIEW_ALL'); ?></a></div><?php if(!$this->forms): ?><div class="df-empty"><?php echo Text::_('COM_DECAROFORMS_NO_FORMS'); ?></div><?php else: foreach($this->forms as $f): ?><div class="df-row"><div><strong><?php echo htmlspecialchars($f['title'],ENT_QUOTES,'UTF-8'); ?></strong><small><?php echo $f['last_submission']?htmlspecialchars($f['last_submission'],ENT_QUOTES,'UTF-8'):Text::_('COM_DECAROFORMS_NO_SUBMISSIONS'); ?></small></div><div class="df-num"><?php echo (int)$f['submission_count']; ?></div></div><?php endforeach; endif; ?></section>
<section class="df-dashboard-card"><div class="df-dashboard-card-head"><h3><?php echo Text::_('COM_DECAROFORMS_RECENT'); ?></h3><a href="<?php echo $this->recentUrl; ?>"><?php echo Text::_('COM_DECAROFORMS_VIEW_ALL'); ?></a></div><?php if(!$this->recent): ?><div class="df-empty"><?php echo Text::_('COM_DECAROFORMS_NO_SUBMISSIONS'); ?></div><?php else: foreach($this->recent as $r): ?><a class="df-row" style="color:inherit;text-decoration:none" href="<?php echo Route::_('index.php?option=com_decaroforms&view=submission&id='.(int)$r['id'],false); ?>"><div><strong><?php echo htmlspecialchars($r['form_title'],ENT_QUOTES,'UTF-8'); ?></strong><small><?php echo htmlspecialchars($r['reference'].' · '.$r['email'],ENT_QUOTES,'UTF-8'); ?></small></div><small><?php echo htmlspecialchars($r['created_at'],ENT_QUOTES,'UTF-8'); ?></small></a><?php endforeach; endif; ?></section></div><?php echo FormHelper::footer(); ?></div>
